<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\OAuthTokenException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\ConsentRequiredException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\ClientScopeConsentRequiredException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\MfaRequiredException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\NewMfaRequiredException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\NewPasswordRequiredException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\NotAllowedAccessUserException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\UnknownUserException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\WrongCredentialsException;

final class OAuthExceptionsUnitTest extends TestCase
{
    // --- OAuthTokenException ---

    public function test_oauth_token_exception_invalid_request(): void
    {
        $ex = OAuthTokenException::invalidRequest('bad param');
        $this->assertSame('invalid_request', $ex->error());
        $this->assertSame(400, $ex->statusCode());
        $this->assertSame('bad param', $ex->getMessage());
    }

    public function test_oauth_token_exception_invalid_grant(): void
    {
        $ex = OAuthTokenException::invalidGrant();
        $this->assertSame('invalid_grant', $ex->error());
        $this->assertSame(400, $ex->statusCode());
    }

    public function test_oauth_token_exception_invalid_client(): void
    {
        $ex = OAuthTokenException::invalidClient();
        $this->assertSame('invalid_client', $ex->error());
        $this->assertSame(401, $ex->statusCode());
    }

    public function test_oauth_token_exception_unauthorized_client(): void
    {
        $ex = OAuthTokenException::unauthorizedClient();
        $this->assertSame('unauthorized_client', $ex->error());
        $this->assertSame(400, $ex->statusCode());
    }

    public function test_oauth_token_exception_invalid_scope(): void
    {
        $ex = OAuthTokenException::invalidScope('scope X not allowed');
        $this->assertSame('invalid_scope', $ex->error());
        $this->assertSame('scope X not allowed', $ex->getMessage());
    }

    // --- LoginException ---

    public function test_login_exception_stores_auth_result(): void
    {
        $auth = new AuthenticationResult(valid: false, error: 'err');
        $ex = new LoginException($auth, 'msg', 401);
        $this->assertSame($auth, $ex->auth);
        $this->assertSame(401, $ex->getCode());
        $this->assertNull($ex->challenges);
    }

    public function test_login_exception_stores_challenges(): void
    {
        $auth = new AuthenticationResult(valid: false);
        $challenges = new ChallengesState(withMfa: true, session: false, username: 'u');
        $ex = new LoginException($auth, '', 401, null, $challenges);
        $this->assertSame($challenges, $ex->challenges);
    }

    // --- ConsentRequiredException ---

    public function test_consent_required_exception_create(): void
    {
        $ex = ConsentRequiredException::create();
        $this->assertInstanceOf(LoginException::class, $ex);
        $this->assertSame(AuthenticationResult::ERR_CONSENT_REQUIRED, $ex->auth->error);
        $this->assertSame(401, $ex->getCode());
        $this->assertNull($ex->challenges);
    }

    public function test_consent_required_exception_with_challenges(): void
    {
        $c = new ChallengesState();
        $ex = ConsentRequiredException::create($c);
        $this->assertSame($c, $ex->challenges);
    }

    // --- ClientScopeConsentRequiredException ---

    public function test_client_scope_consent_required(): void
    {
        $ex = ClientScopeConsentRequiredException::create();
        $this->assertSame(AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED, $ex->auth->error);
        $this->assertSame(401, $ex->getCode());
    }

    // --- MfaRequiredException ---

    public function test_mfa_required(): void
    {
        $ex = MfaRequiredException::create();
        $this->assertSame(AuthenticationResult::ERR_MFA_REQUIRED, $ex->auth->error);
        $this->assertSame(401, $ex->getCode());
    }

    // --- NewMfaRequiredException ---

    public function test_new_mfa_required(): void
    {
        $ex = NewMfaRequiredException::create();
        $this->assertSame(AuthenticationResult::ERR_NEW_MFA_REQUIRED, $ex->auth->error);
    }

    // --- NewPasswordRequiredException ---

    public function test_new_password_required(): void
    {
        $ex = NewPasswordRequiredException::create();
        $this->assertSame(AuthenticationResult::ERR_NEW_PASSWORD_REQUIRED, $ex->auth->error);
    }

    // --- NotAllowedAccessUserException ---

    public function test_not_allowed_access(): void
    {
        $ex = NotAllowedAccessUserException::create('t', 'user');
        $this->assertSame(AuthenticationResult::ERR_NOT_ALLOWED_ACCESS, $ex->auth->error);
        $this->assertSame(403, $ex->getCode());
    }

    // --- UnknownUserException ---

    public function test_unknown_user(): void
    {
        $ex = UnknownUserException::create('t', 'user');
        $this->assertSame(AuthenticationResult::ERR_UNKNOW_USER, $ex->auth->error);
        $this->assertSame(401, $ex->getCode());
    }

    // --- WrongCredentialsException ---

    public function test_wrong_credentials(): void
    {
        $ex = WrongCredentialsException::create('t', 'user');
        $this->assertSame(AuthenticationResult::ERR_WRONG_CREDENTIAL, $ex->auth->error);
        $this->assertSame(401, $ex->getCode());
    }

    public function test_wrong_credentials_with_challenges(): void
    {
        $c = new ChallengesState();
        $ex = WrongCredentialsException::create('t', 'user', $c);
        $this->assertSame($c, $ex->challenges);
    }
}
